def csvsave(name,heads,rows):
    with (DATA/f'{name}.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f);w.writerow(heads);w.writerows(rows)
    return name+'.csv'
def plot(name,title,xlabel,ylabel,series,xlim=None,ylim=None,yscale=None,points=None):
    fig,ax=plt.subplots(figsize=(7.1,4.4))
    for x,y,label in series: ax.plot(x,y,label=label)
    if points:
        for x,y,label in points: ax.scatter(x,y,label=label,zorder=5)
    if any(s[2] for s in series) or points: ax.legend(fontsize=8)
    ax.set_title(title);ax.set_xlabel(xlabel);ax.set_ylabel(ylabel);ax.grid(True,alpha=.25)
    if xlim: ax.set_xlim(*xlim)
    if ylim: ax.set_ylim(*ylim)
    if yscale: ax.set_yscale(yscale)
    fig.savefig(FIGS/f'{name}.svg');plt.close(fig)
def svg(name,body,w=820,h=440):
    txt=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><style>text{{font-family:Arial,sans-serif;fill:#14213d}}.s{{stroke:#14213d;stroke-width:3;fill:none}}.f{{fill:#f7f1e3;stroke:#b58b2a;stroke-width:2}}.g{{stroke:#b58b2a;stroke-width:3;fill:none}}.d{{stroke:#5b6472;stroke-width:2;stroke-dasharray:8 7;fill:none}}</style>{body}</svg>'''
    (FIGS/f'{name}.svg').write_text(txt,encoding='utf-8')
